import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] player1 = new int[n];
        int[] player2 = new int[n];

        for (int i = 0; i < n; i++) {
            player1[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            player2[i] = sc.nextInt();
        }

        process(n, player1, player2);
        sc.close();
    }

    public static void process(int n, int[] p1, int[] p2) {
        int wins = 0;
        int[] p2Extended = new int[n + 1];
        System.arraycopy(p2, 0, p2Extended, 0, n);
        p2Extended[n] = p2[0];

        for (int i = 0; i < 3; i++) {
            wins += Math.min(p1[i], p2Extended[i + 1]);
        }

        int[] p2Copy = Arrays.copyOf(p2, n);
        int last = p2Copy[n - 1];
        // Rotate p2 to the right by one position
        for (int i = n - 1; i > 0; i--) {
            p2Copy[i] = p2Copy[i - 1];
        }
        p2Copy[0] = last;

        for (int i = 0; i < 3; i++) {
            if (p1[i] > 0) {
                int minVal = Math.min(p1[i], p2Copy[i]);
                p1[i] -= minVal;
                p2Copy[i] -= minVal;
                if (p1[i] > 0) {
                    int minVal2 = Math.min(p1[i], p2Copy[i + 1]);
                    p1[i] -= minVal2;
                    p2Copy[i + 1] -= minVal2;
                }
            }
        }

        int sumP1 = 0;
        for (int val : p1) {
            sumP1 += val;
        }
        System.out.println(sumP1 + " " + wins);
    }
}
